<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLButtonAttributes } from 'svelte/elements'; import { composeEventHandlers } from '../shared/events.js'; import { getComboboxContext } from './combobox-context.svelte.js'; interface Props extends Omit<HTMLButtonAttributes, 'children'> { children?: Snippet; ref?: HTMLButtonElement | null; } let { children, ref = $bindable(null), onclick, ...rest }: Props = $props(); const box = getComboboxContext();</script><button bind:this={ref} {...rest} type="button" aria-label="Clear" disabled={box.disabled || box.readOnly || box.selectedValues.length === 0} onclick={composeEventHandlers(onclick, (event) => { box.clear(event); box.input?.focus(); })}>{@render children?.()}</button>
